"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Press feedback: the element scales down while held. On its own it renders a
 * button around `children`; with `asChild` it lends the effect to its single
 * child instead — use that to wrap a Button, so there is never a button inside
 * a button.
 */
function PressableFeedback({
  children,
  onPress,
  className,
  asChild = false,
}: {
  children: React.ReactNode
  onPress?: () => void
  className?: string
  /** Apply the press effect to the child element instead of wrapping it. */
  asChild?: boolean
}) {
  const [pressed, setPressed] = React.useState(false)
  const classes = cn(
    "transition-transform duration-fast ease-move active:scale-95",
    pressed && "scale-95 opacity-90",
    className
  )
  const handlers = {
    onMouseDown: () => setPressed(true),
    onMouseUp: () => setPressed(false),
    onMouseLeave: () => setPressed(false),
  }

  if (asChild && React.isValidElement(children)) {
    type MouseHandler = (event: React.MouseEvent) => void
    const child = children as React.ReactElement<{
      className?: string
      onClick?: MouseHandler
      onMouseDown?: MouseHandler
      onMouseUp?: MouseHandler
      onMouseLeave?: MouseHandler
    }>
    // Chain the child's own mouse handlers instead of replacing them.
    return React.cloneElement(child, {
      onMouseDown: (event: React.MouseEvent) => {
        child.props.onMouseDown?.(event)
        handlers.onMouseDown()
      },
      onMouseUp: (event: React.MouseEvent) => {
        child.props.onMouseUp?.(event)
        handlers.onMouseUp()
      },
      onMouseLeave: (event: React.MouseEvent) => {
        child.props.onMouseLeave?.(event)
        handlers.onMouseLeave()
      },
      className: cn(child.props.className, classes),
      onClick: (event: React.MouseEvent) => {
        child.props.onClick?.(event)
        onPress?.()
      },
    })
  }

  return (
    <button type="button" onClick={onPress} {...handlers} className={classes}>
      {children}
    </button>
  )
}

export { PressableFeedback }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})
